/**
 * @swagger
 * components:
 *   schemas:
 *     BugWebhookPayload:
 *       type: object
 *       description: Payload sent from Sentry webhook when a new bug or event occurs. This structure directly maps to the Bug and BugEvent models.
 *       properties:
 *         id:
 *           type: string
 *           description: Unique event ID generated by Sentry (not stored directly in DB, but useful for deduplication/logging)
 *           example: "event_12345"
 *         event:
 *           type: object
 *           description: Details about the event captured by Sentry
 *           properties:
 *             type:
 *               type: string
 *               description: The type of the event (maps to Bug.type)
 *               example: "error"
 *             platform:
 *               type: string
 *               description: The platform where the error occurred (maps to Bug.category)
 *               example: "javascript"
 *             message:
 *               type: string
 *               description: Error message (maps to BugEvent.message and Bug.description if present)
 *               example: "TypeError: Cannot read property 'foo' of undefined"
 *             title:
 *               type: string
 *               description: Short title describing the error (used if message is missing, maps to Bug.description)
 *               example: "TypeError on Dashboard page"
 *             level:
 *               type: string
 *               description: Severity level of the event (maps to Bug.level)
 *               enum: [debug, info, warning, error, fatal]
 *               example: "error"
 *       required:
 *         - id
 *         - event
 *
 *     BugWebhookResponse:
 *       type: object
 *       description: Response returned after successfully processing a Sentry webhook event.
 *       properties:
 *         success:
 *           type: boolean
 *           description: Indicates if the webhook was processed successfully
 *           example: true
 *         message:
 *           type: string
 *           description: Descriptive message about the webhook processing status
 *           example: "Sentry bug received and stored successfully"
 *         data:
 *           $ref: '#/components/schemas/Bug'
 */
